namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    public static int Calculate(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyCents = LoyaltyDiscountPolicy.Calculate(subtotalCents, tier);
        var promoCents = PromoCodePolicy.Calculate(promoCode, subtotalCents - loyaltyCents);
        return Math.Min(subtotalCents, loyaltyCents + promoCents);
    }
}
