p='CheckoutPricing.Application/CalculateLoyaltyDiscount.cs'
s=open(p).read()
s=s.replace("""    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query) =>
        new(query.SubtotalCents, 0, query.SubtotalCents, query.LoyaltyTier);""","""    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
    {
        var discountCents = DiscountPolicy.Calculate(query.SubtotalCents, query.LoyaltyTier, query.PromoCode);
        return new(query.SubtotalCents, discountCents, query.SubtotalCents - discountCents, query.LoyaltyTier);
    }""")
open(p,'w').write(s)
p='CheckoutPricing.Application/CalculateShippingFee.cs'
s=open(p).read()
s=s.replace("=> 0;","=>\n        ShippingFeePolicy.Calculate(query.PayableTotalCents, query.LoyaltyTier, query.Express);")
open(p,'w').write(s)
p='CheckoutPricing.Application/QuoteCheckout.cs'
s=open(p).read()
s=s.replace("""    public CheckoutQuote Handle(QuoteCheckoutQuery query) => new(0, 0, 0);""","""    public CheckoutQuote Handle(QuoteCheckoutQuery query)
    {
        var discount = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(query.SubtotalCents, query.LoyaltyTier, query.PromoCode));
        var shippingCents = new CalculateShippingFee()
            .Handle(new CalculateShippingFeeQuery(discount.TotalCents, query.LoyaltyTier, query.Express));
        return new(discount.TotalCents, shippingCents, discount.TotalCents + shippingCents);
    }""")
open(p,'w').write(s)
